#include <bits/stdc++.h>
using namespace std;

long long calculate(const vector<long long>&prefix, int total , int count, int paircount){
    return 3*prefix[total-2*count - paircount] + prefix[count + 2*paircount] + 2*prefix[count];
}

vector<long long> prefixSum(vector<long long>&ratings){
    sort(ratings.rbegin(), ratings.rend());
    vector<long long>prefix(ratings.size() + 1, 0);
    
    int i = 0 ; 
    while(i< ratings.size()){
        prefix[i+1] = prefix[i] + ratings[i];
        i++;
    }
    
    return prefix;
}

long long calculateBest(const vector<long long>&prefix, int n , int count){
    int high = n - count , low = 0;
    int total  = 3*n;
    
    while(low<high){
        int mid = low + (high - low) / 2; 
        if(calculate(prefix, total, count , mid+ 1) <= calculate(prefix, total, count, mid)) high = mid;
        else low = mid +1 ; 
    }
    
    return calculate(prefix, total , count, low);
    
}

long long solve(int n , vector<long long>&ratings){
    long long ans = 0; 
    vector<long long> prefix = prefixSum(ratings);
    
    for(int i = n; i>=0 ; i--){
        ans  = max(calculateBest(prefix, n, i), ans);
    }
    
    return ans;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
	// your code goes here
	int t ; 
	cin >> t;
	
	while(t--){
	    int n ; 
	    cin >> n; 
	    
	    vector<long long> ratings(3*n);
	    for(auto &r : ratings){
	        cin >> r;
	    }
	    
	    cout << solve(n, ratings ) << "\n";
	}
	
	return 0;
}
